Which value wins a tie for largest-of-three numeric output?
#include <stdio.h>

int main(void)
{
    int a = 9, b = 9, c = 4;
    int best = a >= b ? a : b;
    if (c > best) {
        best = c;
    }
    printf("%d\n", best);
    return 0;
}
